do $$ declare u record; begin for u in select user_id from core.users where user_id in ('7e65c188-8d8f-4ab3-b203-02cb57f15b23','55d7d556-8ecf-4aa3-a79b-abc3273a1bbe','f606248b-c0d2-4c5c-867c-76250ee3c5fa','97547258-839d-446c-90e4-11dd514ed93b','7ce422ba-50c0-4c77-b186-419a351bd996','5d6e6546-692f-4c60-8ba1-ed6bb31202cb','f24cbe95-3925-4c40-892c-d4bc9b93df09','8e328710-5af2-4512-b412-5a3f044890c7','99bf1a61-9d08-4024-9836-2f8c62959a14','14b23b44-495f-4ee8-b483-3b123291376f','0673ffa8-a2c7-4db7-8ca2-c42827ce95d7','9a9e4456-f1ac-4d00-a86e-6ba9bc6b583b','3c7b41af-6c08-40b4-9856-5639aa236ca1','f14a3bb3-7c2f-4152-b3c4-a24bc7d67b4f','4acc6a63-3c76-4f12-8e0b-067344190823','cde736f2-b0bd-4d76-a9e5-62132e7844ad','807f2396-5ffa-4311-9b02-86602dfb8737','c80acecd-fe13-4300-a659-39a97b38f3d7','a05718ce-691c-4ad9-a5a6-f6927d79b5f5','4e81b8a7-9810-461d-ac72-ef236966f835') and account_status='limited' loop perform core.change_account_status(u.user_id,'active','system',null,'verification_completed'); end loop; end $$;
do $$ declare u record; begin for u in select user_id from core.users where user_id in ('cde736f2-b0bd-4d76-a9e5-62132e7844ad','807f2396-5ffa-4311-9b02-86602dfb8737','c80acecd-fe13-4300-a659-39a97b38f3d7') and account_status='active' loop perform core.change_account_status(u.user_id,'suspended','admin','synthetic-admin','policy_violation',clock_timestamp()+interval '7 days','synthetic-suspension-'||u.user_id::text); end loop; end $$;
